const STATIC_SCREEN_EVENT_MASK_RANGETIMING_DOUBLE_BUFFER_UPDATE_EN: u32 = 0x100;

unsafe fn apply_front_porch_workaround(t: *mut dc_crtc_timing) {
    if (*t).flags.INTERLACE == 1 { if (*t).v_front_porch < 2 { (*t).v_front_porch = 2; } }
    else if (*t).v_front_porch < 1 { (*t).v_front_porch = 1; }
}

pub unsafe fn optc1_program_global_sync(o: *mut timing_generator, vr: i32, vs: i32, vu: i32, vw: i32, pk: i32) {
    let p = DCN10TG_FROM_TG(o); (*p).vready_offset=vr; (*p).vstartup_start=vs; (*p).vupdate_offset=vu; (*p).vupdate_width=vw; (*p).pstate_keepout=pk;
    if (*p).vstartup_start == 0 { BREAK_TO_DEBUGGER!(); return; }
    REG_SET!(OTG_VSTARTUP_PARAM,0,VSTARTUP_START,(*p).vstartup_start);
    REG_SET_2!(OTG_VUPDATE_PARAM,0,VUPDATE_OFFSET,(*p).vupdate_offset,VUPDATE_WIDTH,(*p).vupdate_width);
    REG_SET!(OTG_VREADY_PARAM,0,VREADY_OFFSET,(*p).vready_offset);
}
