pub unsafe fn optc1_enable_optc_clock(o:*mut timing_generator,e:bool){let p=DCN10TG_FROM_TG(o);if e{REG_UPDATE_2!(OPTC_INPUT_CLOCK_CONTROL,OPTC_INPUT_CLK_EN,1,OPTC_INPUT_CLK_GATE_DIS,1);REG_WAIT!(OPTC_INPUT_CLOCK_CONTROL,OPTC_INPUT_CLK_ON,1,1,1000);REG_UPDATE_2!(OTG_CLOCK_CONTROL,OTG_CLOCK_EN,1,OTG_CLOCK_GATE_DIS,1);REG_WAIT!(OTG_CLOCK_CONTROL,OTG_CLOCK_ON,1,1,1000);}else{if (*o).funcs.is_optc_underflow_occurred(o)==true{(*o).funcs.clear_optc_underflow(o);}REG_UPDATE_2!(OTG_CLOCK_CONTROL,OTG_CLOCK_GATE_DIS,0,OTG_CLOCK_EN,0);REG_UPDATE_2!(OPTC_INPUT_CLOCK_CONTROL,OPTC_INPUT_CLK_GATE_DIS,0,OPTC_INPUT_CLK_EN,0);}}
unsafe fn optc1_enable_crtc(o:*mut timing_generator)->bool{let p=DCN10TG_FROM_TG(o);REG_UPDATE!(OPTC_DATA_SOURCE_SELECT,OPTC_SRC_SEL,(*o).inst);REG_UPDATE!(CONTROL,VTG0_ENABLE,1);REG_UPDATE_2!(OTG_CONTROL,OTG_DISABLE_POINT_CNTL,3,OTG_MASTER_EN,1);true}
