pub unsafe fn optc1_validate_timing(o:*mut timing_generator,t:*const dc_crtc_timing)->bool{let p=DCN10TG_FROM_TG(o);ASSERT!(!t.is_null());let vb=(*t).v_total-(*t).v_addressable-(*t).v_border_top-(*t).v_border_bottom;let hb=(*t).h_total-(*t).h_addressable-(*t).h_border_right-(*t).h_border_left;if (*t).timing_3d_format!=TIMING_3D_FORMAT_NONE&&(*t).timing_3d_format!=TIMING_3D_FORMAT_HW_FRAME_PACKING&&(*t).timing_3d_format!=TIMING_3D_FORMAT_TOP_AND_BOTTOM&&(*t).timing_3d_format!=TIMING_3D_FORMAT_SIDE_BY_SIDE&&(*t).timing_3d_format!=TIMING_3D_FORMAT_FRAME_ALTERNATE&&(*t).timing_3d_format!=TIMING_3D_FORMAT_INBAND_FA{return false;}if (*t).flags.INTERLACE==1{return false;}if (*t).h_total>(*p).max_h_total||(*t).v_total>(*p).max_v_total||hb<(*p).min_h_blank||(*t).h_sync_width<(*p).min_h_sync_width||(*t).v_sync_width<(*p).min_v_sync_width{return false;}let mv=if (*t).flags.INTERLACE{(*p).min_v_blank_interlace}else{(*p).min_v_blank};vb>=mv}
