pub unsafe fn optc1_get_otg_active_size(o:*mut timing_generator,w:*mut u32,h:*mut u32)->bool{let _p=DCN10TG_FROM_TG(o);let(mut en,mut vs,mut ve,mut hs,mut he)=(0,0,0,0,0);REG_GET!(OTG_CONTROL,OTG_MASTER_EN,&mut en);if en==0{return false;}REG_GET_2!(OTG_V_BLANK_START_END,OTG_V_BLANK_START,&mut vs,OTG_V_BLANK_END,&mut ve);REG_GET_2!(OTG_H_BLANK_START_END,OTG_H_BLANK_START,&mut hs,OTG_H_BLANK_END,&mut he);*w=hs-he;*h=vs-ve;true}

